class Solution:
    def assignTasks(self, servers: List[int], tasks: List[int]) -> List[int]:
        n = len(servers)
        free_at = [-1] * n
        ans = []
        time = 0
        for j, t in enumerate(tasks):
            time = max(time, j)
            while True:
                best = -1
                for i in range(n):
                    if free_at[i] <= time and (best == -1 or (servers[i], i) < (servers[best], best)):
                        best = i
                if best != -1:
                    break
                time = min(f for f in free_at if f > time)
            free_at[best] = time + t
            ans.append(best)
        return ans

