class Solution {
    public int[] assignTasks(int[] servers, int[] tasks) {
        int n = servers.length;
        long[] freeAt = new long[n];
        Arrays.fill(freeAt, -1);
        int[] ans = new int[tasks.length];
        long time = 0;
        for (int j = 0; j < tasks.length; j++) {
            time = Math.max(time, j);
            int best = -1;
            while (true) {
                best = -1;
                for (int i = 0; i < n; i++)
                    if (freeAt[i] <= time && (best == -1 || servers[i] < servers[best]
                            || (servers[i] == servers[best] && i < best))) best = i;
                if (best != -1) break;
                long nxt = Long.MAX_VALUE;
                for (int i = 0; i < n; i++) if (freeAt[i] > time) nxt = Math.min(nxt, freeAt[i]);
                time = nxt;
            }
            freeAt[best] = time + tasks[j];
            ans[j] = best;
        }
        return ans;
    }
}

