class Solution {
public:
    vector<int> assignTasks(vector<int>& servers, vector<int>& tasks) {
        int n = servers.size();
        using P = pair<int, int>;
        priority_queue<P, vector<P>, greater<P>> freeQ;
        for (int i = 0; i < n; ++i) freeQ.emplace(servers[i], i);
        using B = array<int, 3>;
        priority_queue<B, vector<B>, greater<B>> busyQ;
        vector<int> ans;
        ans.reserve(tasks.size());
        for (int j = 0; j < (int)tasks.size(); ++j) {
            int time = j;
            while (!busyQ.empty() && busyQ.top()[0] <= time) {
                B s = busyQ.top(); busyQ.pop();
                freeQ.emplace(s[1], s[2]);
            }
            if (freeQ.empty()) {
                time = busyQ.top()[0];
                while (!busyQ.empty() && busyQ.top()[0] == time) {
                    B s = busyQ.top(); busyQ.pop();
                    freeQ.emplace(s[1], s[2]);
                }
            }
            P s = freeQ.top(); freeQ.pop();
            ans.push_back(s.second);
            busyQ.push({time + tasks[j], s.first, s.second});
        }
        return ans;
    }
};

