class Solution {
    public int[] assignTasks(int[] servers, int[] tasks) {
        int n = servers.length, m = tasks.length;
        PriorityQueue<int[]> freeQ = new PriorityQueue<>((a, b) ->
                a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        PriorityQueue<int[]> busyQ = new PriorityQueue<>((a, b) ->
                a[0] != b[0] ? a[0] - b[0] : (a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]));
        for (int i = 0; i < n; i++) freeQ.offer(new int[]{servers[i], i});
        int[] ans = new int[m];
        for (int j = 0; j < m; j++) {
            int time = j;
            while (!busyQ.isEmpty() && busyQ.peek()[0] <= time) {
                int[] s = busyQ.poll();
                freeQ.offer(new int[]{s[1], s[2]});
            }
            if (freeQ.isEmpty()) {
                time = busyQ.peek()[0];
                while (!busyQ.isEmpty() && busyQ.peek()[0] == time) {
                    int[] s = busyQ.poll();
                    freeQ.offer(new int[]{s[1], s[2]});
                }
            }
            int[] s = freeQ.poll();
            ans[j] = s[1];
            busyQ.offer(new int[]{time + tasks[j], s[0], s[1]});
        }
        return ans;
    }
}

