var assignTasks = function(servers, tasks) {
    const less = (a, b) => {
        for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return a[k] < b[k];
        return false;
    };
    const push = (h, v) => {
        h.push(v);
        let i = h.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (less(h[i], h[p])) { const t = h[i]; h[i] = h[p]; h[p] = t; i = p; }
            else break;
        }
    };
    const pop = h => {
        const top = h[0];
        const last = h.pop();
        if (h.length) {
            h[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < h.length && less(h[l], h[m])) m = l;
                if (r < h.length && less(h[r], h[m])) m = r;
                if (m === i) break;
                const t = h[i]; h[i] = h[m]; h[m] = t;
                i = m;
            }
        }
        return top;
    };
    const freeQ = [];
    servers.forEach((w, i) => push(freeQ, [w, i]));
    const busyQ = [];
    const ans = new Array(tasks.length);
    for (let j = 0; j < tasks.length; j++) {
        let time = j;
        while (busyQ.length && busyQ[0][0] <= time) {
            const [, w, i] = pop(busyQ);
            push(freeQ, [w, i]);
        }
        if (!freeQ.length) {
            time = busyQ[0][0];
            while (busyQ.length && busyQ[0][0] === time) {
                const [, w, i] = pop(busyQ);
                push(freeQ, [w, i]);
            }
        }
        const [w, i] = pop(freeQ);
        ans[j] = i;
        push(busyQ, [time + tasks[j], w, i]);
    }
    return ans;
};
